from scipy.stats import norm, t

def var_normal(sigma, position, level=0.99):
    """One-day VaR in £ (a positive loss) for a daily vol sigma, as a fraction."""
    return float(-norm.ppf(1 - level) * sigma * position)

def var_t(sigma, position, nu, level=0.99):
    """The same with Student-t shocks rescaled to variance 1."""
    if nu <= 2:
        raise ValueError("a t with nu <= 2 has no variance")
    q = t.ppf(1 - level, nu) * (((nu - 2) / nu) ** 0.5)
    return float(-q * sigma * position)

import numpy as np
from scipy.stats import norm

def garch_var_series(params, r, n_train, position, dist="normal", nu=5):
    """99% one-day VaR in £ for each day after the first n_train days of r (in %)."""
    sigma = np.sqrt(garch_variance(params, r))[n_train:] / 100
    if dist == "normal":
        return [var_normal(s, position) for s in sigma]
    return [var_t(s, position, nu) for s in sigma]

def expected_shortfall_normal(sigma, position, level=0.99):
    """Average loss in £ on the days beyond the normal VaR."""
    q = norm.ppf(1 - level)
    return float(sigma * norm.pdf(q) / (1 - level) * position)
